import { HrmWorkflowStatus, HrmStatusTone, HRM_WORKFLOW_STATUS } from 'hrm-ui';

/** Trạng thái đơn từ = 'draft' (Nháp, chưa gửi) + trạng thái quy trình chuẩn DS (HrmWorkflowStatus). */
export type ReqStatus = 'draft' | HrmWorkflowStatus;

export type ReqTypeKey = 'leave' | 'business' | 'ot' | 'remote' | 'unpaid';

/** Nhãn loại đơn (dùng chung 2 template Đăng ký + Phê duyệt). */
export const REQ_TYPES: Record<ReqTypeKey, string> = {
  leave: 'Nghỉ phép năm',
  business: 'Đi công tác',
  ot: 'Đăng ký tăng ca',
  remote: 'Làm việc từ xa',
  unpaid: 'Nghỉ không lương',
};

/** 1 dòng đơn từ. */
export interface ReqRow {
  id: number;
  code: string;         // mã đơn — VD "NP-2026-0042"
  type: ReqTypeKey;
  applicant: string;    // người gửi
  dept: string;         // phòng ban
  from: string;         // dd/mm/yyyy
  to: string;
  days: number;         // số ngày / số giờ
  unit: string;         // 'ngày' | 'giờ'
  reason: string;
  status: ReqStatus;
  approver: string;     // người duyệt
  submittedAt: string;  // ngày gửi
  /** Mốc Date (suy từ from/to) cho chế độ Gantt. */
  start?: Date;
  end?: Date;
  [k: string]: unknown;
}

/** Parse "dd/mm/yyyy" → Date (cho Gantt). */
export function parseDMY(s: string): Date {
  const [d, m, y] = s.split('/').map(Number);
  return new Date(y || 2026, (m || 1) - 1, d || 1);
}

/** Rows kèm start/end Date — dùng khởi tạo signal ở 2 template (cho Gantt). */
export function requestRows(): ReqRow[] {
  return REQUESTS.map((r) => ({ ...r, start: parseDMY(r.from), end: parseDMY(r.to) }));
}

/** Meta trạng thái → tông (semantic) + nhãn VN. 'draft' custom; còn lại theo bảng chuẩn DS. */
export function reqStatusMeta(s: ReqStatus): { tone: HrmStatusTone; vi: string } {
  if (s === 'draft') return { tone: 'neutral', vi: 'Nháp' };
  return HRM_WORKFLOW_STATUS[s];
}

