import { Component, computed, input } from '@angular/core';
import { HrmUserCell, HrmStatusCell, HrmTag, HrmApprovalFlow, HrmApprovalStep } from 'hrm-ui';
import { ReqRow, REQ_TYPES, reqStatusMeta } from './_requests';

/** Nội dung CHI TIẾT đơn từ — dùng chung cho peek của cả 2 template (Đăng ký & Phê duyệt).
 *  Cấu trúc & thành phần theo ĐÚNG detail của "Chế độ xem dữ liệu" (SgEmpDetail): nhận diện +
 *  chip trạng thái · các section dl thông tin · quy trình phê duyệt bằng component chuẩn DS
 *  hrm-approval-flow (icon/màu do component lo → đồng bộ, không dùng stroke màu tự chế). */
@Component({
  selector: 'sg-request-detail',
  imports: [HrmUserCell, HrmStatusCell, HrmTag, HrmApprovalFlow],
  template: `
    @if (req(); as r) {
      <div class="pk">
        <!-- Nhận diện + TRẠNG THÁI (chip, giống Chế độ xem dữ liệu). -->
        <div class="pk-head2">
          <hrm-user-cell [name]="r.applicant" [sub]="r.code + ' · ' + r.dept" [colorful]="true" [avatarSize]="44" />
          <hrm-status [status]="meta(r.status).tone" [label]="meta(r.status).vi" variant="badge" [dot]="true" />
        </div>

        <section class="pk-sec">
          <h4 class="pk-h">Thông tin đơn</h4>
          <dl class="pk-list">
            <dt>Loại đơn</dt><dd><hrm-tag color="blue">{{ REQ_TYPES[r.type] }}</hrm-tag></dd>
            <dt>Thời gian</dt><dd>{{ r.from }} → {{ r.to }}</dd>
            <dt>Số lượng</dt><dd>{{ r.days }} {{ r.unit }}</dd>
            <dt>Người duyệt</dt><dd>{{ r.approver }}</dd>
            <dt>Ngày gửi</dt><dd>{{ r.submittedAt }}</dd>
          </dl>
        </section>

        <section class="pk-sec">
          <h4 class="pk-h">Lý do</h4>
          <p class="pk-reason">{{ r.reason }}</p>
        </section>

        <section class="pk-sec">
          <h4 class="pk-h">Quy trình phê duyệt</h4>
          <hrm-approval-flow [steps]="steps()" />
        </section>
      </div>
    }
  `,
  host: { class: 'sg-request-detail' },
  styles: [`
    :host { display: block; }
    :host ::ng-deep .ant-tag { margin: 0; }
    .pk { display: flex; flex-direction: column; gap: var(--space-3-5, 14px); padding: var(--space-4, 16px) var(--space-5, 20px) var(--space-5, 20px); }
    .pk-head2 { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-2, 8px); }
    .pk-sec { border-top: 1px solid var(--border-soft, var(--border-sub)); padding-top: var(--space-3, 12px); }
    .pk-sec:first-child { border-top: 0; padding-top: 0; }
    .pk-h { margin: 0 0 8px; font-size: var(--fs-12, 12px); font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--text-sub); }
    .pk-list { display: grid; grid-template-columns: 118px 1fr; gap: 8px 12px; margin: 0; align-items: center; }
    .pk-list dt { font-size: var(--fs-13, 13px); color: var(--text-sub); }
    .pk-list dd { margin: 0; font-size: var(--fs-13, 13px); color: var(--text-body); min-width: 0; }
    .pk-reason { margin: 0; font-size: var(--fs-13, 13px); color: var(--text-body); line-height: 1.55; }
  `],
})
export class SgRequestDetail {
  readonly req = input.required<ReqRow>();
  protected readonly REQ_TYPES = REQ_TYPES;
  protected meta(s: ReqRow['status']) { return reqStatusMeta(s); }

  /** Quy trình phê duyệt (Gửi đơn → Người duyệt) — trạng thái từng bước suy theo status đơn.
   *  Dùng hrm-approval-flow (chuẩn DS) → icon/màu nhất quán, không tự vẽ dot màu. */
  protected readonly steps = computed<HrmApprovalStep[]>(() => {
    const r = this.req();
    const sent: HrmApprovalStep = {
      title: 'Gửi đơn', name: r.applicant, role: r.dept,
      state: r.status === 'draft' ? 'current' : 'approved',
      stateLabel: r.status === 'draft' ? 'Bản nháp' : 'Đã gửi',
      time: r.submittedAt !== '—' ? r.submittedAt : undefined,
    };
    const approve: HrmApprovalStep = { title: 'Phê duyệt', name: r.approver, role: 'Người duyệt', state: 'waiting' };
    switch (r.status) {
      case 'draft': approve.state = 'waiting'; break;
      case 'pending': approve.state = 'current'; approve.stateLabel = 'Chờ duyệt'; break;
      case 'approved': approve.state = 'approved'; approve.stateLabel = 'Đã duyệt'; break;
      case 'rejected': approve.state = 'rejected'; approve.stateLabel = 'Đã từ chối'; break;
      case 'changeRequested': approve.state = 'current'; approve.stateLabel = 'Yêu cầu thay đổi'; break;
      case 'pendingCancel': approve.state = 'current'; approve.stateLabel = 'Chờ duyệt hủy'; break;
      case 'cancelled': approve.state = 'rejected'; approve.stateLabel = 'Đã hủy'; break;
    }
    return [sent, approve];
  });
}
